// Daily registry check of every watched domain (RDAP). Only emits an alert when a
// domain's registration problems change, so a known issue is reported once.
// The domain list comes from the Domains tab of the Domain Guard sheet.
const DOMAINS = [...new Set($input.all().map(i => String(i.json.Domain ?? '').trim().toLowerCase()).filter(Boolean))];
const EXPIRY_WINDOW_DAYS = 30;
const state = $getWorkflowStaticData('global');
state.flags = state.flags || {};
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const alerts = [];
const skipped = [];

// Registries rate-limit bursts, so retry 429s and server errors with a pause.
const lookup = async (domain) => {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://rdap.org/domain/' + domain, headers: { Accept: 'application/rdap+json' }, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000, json: true });
      if (res.statusCode !== 429 && res.statusCode < 500) return res;
    } catch (e) {
      if (attempt === 3) throw e;
    }
    await sleep(3000 * attempt);
  }
  return { statusCode: 429 };
};

for (const domain of DOMAINS) {
  let problems = [];
  let details = '';
  try {
    const res = await lookup(domain);
    if (res.statusCode === 404) {
      problems = ['not_registered'];
      details = 'Registry has no record of this domain.';
    } else if (res.statusCode === 200) {
      const j = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
      const expires = (j.events || []).find(e => e.eventAction === 'expiration')?.eventDate ?? null;
      const days = expires ? Math.floor((new Date(expires) - new Date()) / 86400000) : null;
      const status = (j.status || []).map(s => s.toLowerCase());
      if (days !== null && days < 0) problems.push('expired');
      else if (days !== null && days <= EXPIRY_WINDOW_DAYS) problems.push('expiring_within_' + EXPIRY_WINDOW_DAYS + '_days');
      if (status.some(s => s.includes('hold'))) problems.push('on_hold');
      if (status.some(s => s.includes('redemption'))) problems.push('redemption_period');
      if (status.some(s => s.includes('pending delete'))) problems.push('pending_delete');
      details = 'Expires ' + (expires || 'unknown') + (days !== null ? ' (' + days + ' days)' : '') + '; registry status: ' + (status.join(', ') || 'none') + '.';
    } else {
      skipped.push(domain);
      continue; // registry hiccup: keep the previous state and try again tomorrow
    }
  } catch (e) {
    skipped.push(domain);
    continue;
  }

  const key = problems.join(',');
  const previous = state.flags[domain] || '';
  if (key && key !== previous) {
    alerts.push({ json: { domain, event_type: 'DOMAIN_' + problems[0].toUpperCase(), details: 'Daily registry check: ' + problems.join(', ') + '. ' + details, source: 'n8n_expiry_sweep', severity_hint: 'high' } });
  } else if (!key && previous) {
    alerts.push({ json: { domain, event_type: 'DOMAIN_RENEWED', details: 'Daily registry check: previous issue (' + previous + ') has cleared. ' + details + ' Verify and resolve if appropriate.', source: 'n8n_expiry_sweep', severity_hint: 'unknown' } });
  }
  state.flags[domain] = key;
  await sleep(1000);
}

// Remember the last run so skipped lookups are visible in the workflow's static data.
state.lastRun = { at: new Date().toISOString(), checked: DOMAINS.length - skipped.length, skipped };
return alerts;
